to March 2012 = 9 years\n# March 2012 to December 2012 = 9/12 = 0.75 years\n# Total = 9.75 years\n\nyears = 9.75\ncagr_foreign_dec = (december_2012 / march_2003) ** (1/years) - 1\n\nprint(\"Option 1: March 2003 to December 2012 (9.75 years)\")\nprint(f\"CAGR: {cagr_foreign_dec*100:.4f}%\")\n\n# Using March 2003 to March 2012 (9 years exactly - matching fiscal years better)\nmarch_2012 = 5147.6\nyears2 = 9\n\ncagr_foreign_mar = (march_2012 / march_2003) ** (1/years2) - 1\n\nprint(f\"\\nOption 2: March 2003 to March 2012 (9 years)\")\nprint(f\"CAGR: {cagr_foreign_mar*100:.4f}%\")\n\n# Using fiscal year data: June 2003 to June 2012\nfiscal_2003 = 1371.9  # June 2003\nfiscal_2012 = 5313.5  # June 2012  \nyears3 = 9\n\ncagr_foreign_fy = (fiscal_2012 / fiscal_2003) ** (1/years3) - 1\n\nprint(f\"\\nOption 3: Fiscal Year data (June 2003 to June 2012, 9 years)\")\nprint(f\"CAGR: {cagr_foreign_fy*100:.4f}%\")\n\n# Check ratio with each interpretation\ngdp_2003 = 11456.45\ngdp_2012 = 16253.97\n\ncagr_gdp = (gdp_2012 / gdp_2003) ** (1/9) - 1\nprint(f\"\\nGDP CAGR (same 9 year period): {cagr_gdp*100:.4f}%\")\n\nprint(f\"\\n--- Ratio calculations ---\")\nprint(f\"Option 1 ratio: {cagr_foreign_dec/cagr_gdp:.4f} -> {round(cagr_foreign_dec/cagr_gdp,1)}\")\nprint(f\"Option 2 ratio: {cagr_foreign_mar/cagr_gdp:.4f} -> {round(cagr_foreign_mar/cagr_gdp,1)}\")\nprint(f\"Option 3 ratio: {cagr_foreign_fy/cagr_gdp:.4f} -> {round(cagr_foreign_fy/cagr_gdp,1)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
